<?php
/** Social links (DB-driven) + inline SVG icons. */

/** @param string $placement header|footer|contact|floating */
function social_links(string $placement): array
{
    static $cache = null;
    if ($cache === null) {
        try {
            $cache = db()->query(
                "SELECT * FROM social_links WHERE is_active = 1 AND url <> '' ORDER BY sort_order, id"
            )->fetchAll();
        } catch (Throwable $e) {
            $cache = [];
        }
    }
    $col = 'show_' . $placement;
    return array_values(array_filter($cache, fn($l) => !empty($l[$col])));
}

